/// Precomputed fee test vectors for all 11 UTXO coins.
///
/// estimateTxFee formula (all coins, identical):
///   (feeRatePerKB * BigInt.from(vSize) ~/ BigInt.from(1000)).toInt()
///
/// roughFeeEstimate SegWit formula (Bitcoin, Litecoin, Fact0rn, Peercoin,
///   Particl, Namecoin):
///   ((42 + (272 * inputCount) + (128 * outputCount)) / 4).ceil()
///     * (feeRatePerKB.toInt() / 1000).ceil()
///
/// roughFeeEstimate Legacy formula (Dash, Dogecoin, Firo, Bitcoin Cash, eCash):
///   ((181 * inputCount) + (34 * outputCount) + 10)
///     * (feeRatePerKB.toInt() / 1000).ceil()

class FeeVector {
  final String coinName;
  final int vSize;
  final BigInt feeRatePerKB;
  final int expectedFee;

  const FeeVector({
    required this.coinName,
    required this.vSize,
    required this.feeRatePerKB,
    required this.expectedFee,
  });

  @override
  String toString() =>
      'FeeVector($coinName, vSize=$vSize, rate=$feeRatePerKB, '
      'expected=$expectedFee)';
}

class RoughFeeVector {
  final String coinName;
  final int inputCount;
  final int outputCount;
  final BigInt feeRatePerKB;
  final BigInt expectedRawValue;
  final int fractionDigits;

  const RoughFeeVector({
    required this.coinName,
    required this.inputCount,
    required this.outputCount,
    required this.feeRatePerKB,
    required this.expectedRawValue,
    required this.fractionDigits,
  });

  @override
  String toString() =>
      'RoughFeeVector($coinName, in=$inputCount, out=$outputCount, '
      'rate=$feeRatePerKB, expected=$expectedRawValue, '
      'fd=$fractionDigits)';
}

// ---------------------------------------------------------------------------
// estimateTxFee vectors
// ---------------------------------------------------------------------------
//
// Formula: (feeRatePerKB * BigInt.from(vSize) ~/ BigInt.from(1000)).toInt()
//
// This is BigInt integer division (truncation toward zero), NOT .ceil().
// Example: 999 * 154 ~/ 1000 = 153846 ~/ 1000 = 153 (NOT 154).

/// All 11 UTXO coins sharing the same estimateTxFee formula.
const List<String> kAllUtxoCoins = [
  'Bitcoin',
  'Litecoin',
  'Bitcoin Cash',
  'Namecoin',
  'Firo',
  'Particl',
  'Dash',
  'Dogecoin',
  'eCash',
  'Fact0rn',
  'Peercoin',
];

/// Boundary vSize values for testing.
const List<int> kVSizes = [1, 100, 141, 154, 200, 500, 100000];

/// Boundary feeRatePerKB values for testing.
final List<BigInt> kFeeRates = [
  BigInt.zero,
  BigInt.from(999),
  BigInt.from(1000),
  BigInt.from(1001),
  BigInt.from(5000),
  BigInt.from(10000),
  BigInt.from(100000),
];

/// Compute expected estimateTxFee result using the actual formula.
int _computeEstimateTxFee(int vSize, BigInt feeRatePerKB) {
  return (feeRatePerKB * BigInt.from(vSize) ~/ BigInt.from(1000)).toInt();
}

/// Precomputed estimateTxFee vectors for all 11 coins at boundary conditions.
///
/// Since the formula is identical for all coins, vectors are generated per coin
/// for test grouping clarity, but expected values are the same across coins.
final List<FeeVector> kEstimateTxFeeVectors = [
  for (final coin in kAllUtxoCoins)
    for (final vSize in kVSizes)
      for (final rate in kFeeRates)
        FeeVector(
          coinName: coin,
          vSize: vSize,
          feeRatePerKB: rate,
          expectedFee: _computeEstimateTxFee(vSize, rate),
        ),
];

// ---------------------------------------------------------------------------
// roughFeeEstimate vectors -- SegWit
// ---------------------------------------------------------------------------
//
// SegWit coins: Bitcoin, Litecoin, Fact0rn, Peercoin, Particl, Namecoin
//
// Formula:
//   effectiveVSize = ((42 + (272 * inputCount) + (128 * outputCount)) / 4).ceil()
//   fee = effectiveVSize * (feeRatePerKB.toInt() / 1000).ceil()

/// SegWit coin names and their fractionDigits.
const Map<String, int> kSegWitCoins = {
  'Bitcoin': 8,
  'Litecoin': 8,
  'Fact0rn': 8,
  'Peercoin': 6,
  'Particl': 8,
  'Namecoin': 8,
};

const List<int> kInputCounts = [1, 2, 3, 5];
const List<int> kOutputCounts = [1, 2, 3];

final List<BigInt> kRoughFeeRates = [
  BigInt.zero,
  BigInt.from(999),
  BigInt.from(1000),
  BigInt.from(1001),
  BigInt.from(5000),
  BigInt.from(10000),
  BigInt.from(100000),
];

/// Compute SegWit roughFeeEstimate expected raw value.
BigInt _computeSegWitRoughFee(
  int inputCount,
  int outputCount,
  BigInt feeRatePerKB,
) {
  final effectiveVSize =
      ((42 + (272 * inputCount) + (128 * outputCount)) / 4).ceil();
  final feeRateCeil = (feeRatePerKB.toInt() / 1000).ceil();
  return BigInt.from(effectiveVSize * feeRateCeil);
}

/// Precomputed SegWit roughFeeEstimate vectors.
final List<RoughFeeVector> kSegWitRoughFeeVectors = [
  for (final entry in kSegWitCoins.entries)
    for (final inCount in kInputCounts)
      for (final outCount in kOutputCounts)
        for (final rate in kRoughFeeRates)
          RoughFeeVector(
            coinName: entry.key,
            inputCount: inCount,
            outputCount: outCount,
            feeRatePerKB: rate,
            expectedRawValue:
                _computeSegWitRoughFee(inCount, outCount, rate),
            fractionDigits: entry.value,
          ),
];

// ---------------------------------------------------------------------------
// roughFeeEstimate vectors -- Legacy
// ---------------------------------------------------------------------------
//
// Legacy coins: Dash, Dogecoin, Firo, Bitcoin Cash, eCash
//
// Formula:
//   legacySize = (181 * inputCount) + (34 * outputCount) + 10
//   fee = legacySize * (feeRatePerKB.toInt() / 1000).ceil()

/// Legacy coin names and their fractionDigits.
const Map<String, int> kLegacyCoins = {
  'Dash': 8,
  'Dogecoin': 8,
  'Firo': 8,
  'Bitcoin Cash': 8,
  'eCash': 2,
};

/// Compute Legacy roughFeeEstimate expected raw value.
BigInt _computeLegacyRoughFee(
  int inputCount,
  int outputCount,
  BigInt feeRatePerKB,
) {
  final legacySize = (181 * inputCount) + (34 * outputCount) + 10;
  final feeRateCeil = (feeRatePerKB.toInt() / 1000).ceil();
  return BigInt.from(legacySize * feeRateCeil);
}

/// Precomputed Legacy roughFeeEstimate vectors.
final List<RoughFeeVector> kLegacyRoughFeeVectors = [
  for (final entry in kLegacyCoins.entries)
    for (final inCount in kInputCounts)
      for (final outCount in kOutputCounts)
        for (final rate in kRoughFeeRates)
          RoughFeeVector(
            coinName: entry.key,
            inputCount: inCount,
            outputCount: outCount,
            feeRatePerKB: rate,
            expectedRawValue:
                _computeLegacyRoughFee(inCount, outCount, rate),
            fractionDigits: entry.value,
          ),
];
